require_once dirname(__DIR__,2).'/config/config.php';require_once dirname(__DIR__,2).'/config/database.php';require_once dirname(__DIR__,2).'/config/functions.php';require_once dirname(__DIR__,2).'/config/session.php';require_once dirname(__DIR__,2).'/config/sponsor_assignments.php';require_once dirname(__DIR__,2).'/modules/accounting/lib_transaction_review.php';Session::start();
if(!Session::isLoggedIn()){http_response_code(403);exit('Forbidden');}$role=Session::getUserRole();$uid=(int)Session::getUserId();if(!in_array($role,['supervisor','financial_manager','admin','accountant_staff'],true)){http_response_code(403);exit('Forbidden');}$id=(int)($_GET['id']??0);$p=$id>0?dbFetchOne("SELECT sp.*,s.full_name sponsor_name,s.supervisor_id,s.first_letter_id,s.gender FROM sponsor_payments sp LEFT JOIN sponsors s ON s.id=sp.sponsor_id WHERE sp.id=?",[$id]):null;if(!$p||empty($p['receipt_file_path'])){http_response_code(404);exit('Not found');}if($role==='supervisor'&&((int)$p['supervisor_id']!==$uid&&!supervisorCanAccessSponsor($uid,$p))){http_response_code(403);exit('Forbidden');}$relative=ltrim((string)$p['receipt_file_path'],'/\\');if(strpos($relative,'..')!==false||strpos($relative,'storage/receipts/')!==0){http_response_code(400);exit('Invalid receipt path');}$base=realpath(dirname(__DIR__,2).'/storage/receipts');$path=realpath(dirname(__DIR__,2).'/'.$relative);if(!$base||!$path||strpos($path,$base.DIRECTORY_SEPARATOR)!==0||!is_file($path)){http_response_code(404);exit('Not found');}$ext=strtolower(pathinfo($path,PATHINFO_EXTENSION));$types=['jpg'=>'image/jpeg','jpeg'=>'image/jpeg','png'=>'image/png','pdf'=>'application/pdf'];if(!isset($types[$ext])){http_response_code(415);exit('Unsupported file');}header('Content-Type: '.$types[$ext]);header('Content-Length: '.filesize($path));header('Content-Disposition: inline; filename="sponsor-payment-'.$id.'.'.$ext.'"');readfile($path);
